package com.bank.median.service;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.logging.Logger;

// Finds the median of two sorted balance arrays by merging only to the middle.
public class MedianBalanceService {
    private static final Logger log = Logger.getLogger(MedianBalanceService.class.getName());

    public BigDecimal median(long[] a, long[] b) {
        int n = a.length + b.length;
        int mid = n / 2;
        int i = 0, j = 0, consumed = 0;
        long prev = 0, curr = 0;
        while (consumed <= mid) {
            prev = curr;
            if (j >= b.length || (i < a.length && a[i] <= b[j])) {
                curr = a[i++];          // take from array a (two-way merge step)
            } else {
                curr = b[j++];          // take from array b
            }
            consumed++;
        }
        BigDecimal result;
        if (n % 2 == 1) {
            result = BigDecimal.valueOf(curr);                       // odd: single middle
        } else {
            result = BigDecimal.valueOf(prev + curr)
                     .divide(BigDecimal.valueOf(2), 2, RoundingMode.HALF_UP);  // even: average
        }
        final BigDecimal r = result;
        log.info(() -> "Median balance = Rs." + r);
        return result;
    }
}
